fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool {
    // An empty array or an array with one element has only one distinct value
    if arr.len() <= 1 {
        return true;
    }
    
    // Get the first element to compare with the rest
    let first_element = arr[0];
    
    // Check if all elements are equal to the first element
    for &element in arr.iter() {
        if element != first_element {
            return false;
        }
    }
    
    true
}